const raw = $input.first().json;
let data = raw;
if (raw.body !== undefined) {
  let rawBody = raw.body;
  if (typeof rawBody === 'string') {
    rawBody = rawBody.replace(/^=+/, '').trim();
    try { data = JSON.parse(rawBody); } catch(e) { data = raw; }
  } else if (typeof rawBody === 'object') { data = rawBody; }
}

function sanitize(s) { return String(s || '').substring(0, 10000); }

const userRequest = sanitize(data.userRequest || data.prompt || data.description || data.request || '');
const arch        = data.architecture || {};
const stack       = arch.stack        || 'Node.js/Express';
const mvpScope    = arch.mvp_scope    || userRequest.substring(0, 100);
const endpoints   = arch.priority_endpoints || [];
const dataModel   = arch.data_model   || {};
const stores      = arch.stores       || {};
const deployUrl   = data.deploy_url   || null;

// Priorité : project_name de l'Architect > extraction depuis mvp_scope
const rawProjectName = arch.project_name || data.project_name || '';
let projectName = '';
if (rawProjectName && rawProjectName.length > 1) {
  projectName = rawProjectName.trim();
} else if (mvpScope) {
  // Extraire nom depuis mvp_scope en supprimant les mots génériques
  projectName = mvpScope
    .replace(/^cr[eéè]er\s+(une?\s+)?/i, '')
    .replace(/^(une?|le|la|les)\s+/i, '')
    .split(' ').slice(0, 3).join(' ')
    .trim();
  projectName = projectName.charAt(0).toUpperCase() + projectName.slice(1);
}
if (!projectName || projectName.length < 2) projectName = 'Application';

if (!data.task_id) {
  return [{ json: { error_code: "VALIDATION_ERROR", error_message: "task_id manquant", timestamp: new Date().toISOString() } }];
}
if (!userRequest) {
  return [{ json: { error_code: "VALIDATION_ERROR", error_message: "userRequest manquant", timestamp: new Date().toISOString() } }];
}

// Construire contexte API
let apiDocs = '';
if (endpoints.length > 0) {
  apiDocs = '\n\nENDPOINTS API :\n';
  endpoints.forEach(ep => { apiDocs += '- ' + ep.method + ' ' + ep.path + ' : ' + (ep.description || '') + '\n'; });
}

// Champs requis par ressource
let storeDocs = '';
if (Object.keys(stores).length > 0) {
  storeDocs = '\n\nCHAMPS REQUIS PAR RESSOURCE :\n';
  Object.keys(stores).forEach(res => {
    const cfg = stores[res];
    storeDocs += '- POST /' + cfg.store_name + ' : ' + (cfg.required_fields || []).join(', ') + '\n';
  });
}

// Exemples curl
let curlExamples = '';
endpoints.forEach(ep => {
  if (ep.path === '/health') {
    curlExamples += 'curl http://localhost:3000/health\n';
  } else if (ep.method === 'GET') {
    curlExamples += 'curl http://localhost:3000' + ep.path + '\n';
  } else if (ep.method === 'POST') {
    const seg = ep.path.replace(/^\//, '').split('/')[0];
    const resName = seg.replace(/s$/, '');
    const reqFields = stores[resName]?.required_fields || [];
    if (reqFields.length > 0) {
      const exBody = reqFields.reduce((acc, f) => {
        acc[f] = (dataModel[resName]?.[f] === 'number') ? 1 : 'exemple';
        return acc;
      }, {});
      curlExamples += 'curl -X POST http://localhost:3000' + ep.path + ' \\\n';
      curlExamples += '  -H "Content-Type: application/json" \\\n';
      curlExamples += '  -d \'' + JSON.stringify(exBody) + '\'\n';
    }
  }
  curlExamples += '\n';
});

const improvementPrompts = [
  'Ajoute un bouton Supprimer sur chaque element de la liste',
  'Affiche ' + (Object.values(stores)[0]?.required_fields?.[1] || 'le titre') + ' et ' + (Object.values(stores)[0]?.required_fields?.[2] || 'la description') + ' dans le titre de chaque item',
  'Ajoute un systeme de statut sur les reservations (en_attente, acceptee, refusee, livree)',
  'Ajoute une liste deroulante qui charge automatiquement les trajets disponibles dans le formulaire de reservation',
  'Ajoute la validation que tous les champs numeriques sont des nombres positifs'
];

const systemPrompt = `Tu es un expert en documentation technique.
REGLE ABSOLUE : Retourner UNIQUEMENT un objet JSON valide.

FORMAT :
{
  "agent": "documentation",
  "files": [
    { "path": "README.md", "content": "..." }
  ],
  "errors": []
}

SECTIONS OBLIGATOIRES DU README :
1. Titre H1 = NOM DU PROJET (utiliser EXACTEMENT : ${projectName})
2. Vue d ensemble du projet
3. Ce que genere le pipeline (architecture, stack, fichiers produits)
4. Prerequis et Installation
5. Configuration (.env) — IMPORTANT : la stack utilise SQLite (better-sqlite3), PAS de serveur de base de donnees externe. Les SEULES variables .env sont EXACTEMENT : PORT (port du serveur, defaut 3000), DB_PATH (chemin du fichier SQLite, defaut ./database.db), NODE_ENV. NE JAMAIS inventer DB_HOST, DB_USER, DB_PASSWORD, DB_NAME ni aucune variable de connexion MySQL/PostgreSQL/MongoDB : elles n existent pas dans cette stack.
6. Demarrage (npm start / start.bat / start.sh)
7. Documentation API complete avec exemples curl
8. Modele de donnees
9. Guide d amelioration — expliquer que l app est generee automatiquement
10. Exemples de prompts d amelioration
11. Limitations MVP Phase 1 — IMPORTANT : les donnees SONT persistantes (SQLite, fichier database.db conserve apres redemarrage). NE PAS ecrire que le stockage est en memoire ni que les donnees sont perdues au redemarrage : c est FAUX. Limitations reelles a mentionner : pas d authentification, pas de matching automatique, MVP fonctionnel mono-utilisateur.
12. Roadmap suggeree (v1.1, v1.2, v1.3)
13. Securite

IMPORTANT : Le titre H1 DOIT etre exactement "${projectName}". Pas de variante.
Commence par { et termine par }.`;

const userPrompt = `Genere la documentation complete pour :

NOM DU PROJET (H1 obligatoire) : ${projectName}
STACK : ${stack}
TASK_ID : ${data.task_id}
${apiDocs}${storeDocs}

EXEMPLES CURL :
${curlExamples}

PROMPTS D AMELIORATION SUGGERES :
${improvementPrompts.map((p, i) => (i+1) + '. "' + p + '"').join('\n')}

CONTEXTE :
${userRequest.substring(0, 2000)}

Retourne UNIQUEMENT le JSON.`;

return [{
  json: {
    task_id:      String(data.task_id),
    userRequest,
    systemPrompt,
    userPrompt
  }
}];

const groqResponse = $input.first().json;
const upstream = $('Inject Prompt').first().json;

const raw = groqResponse.choices?.[0]?.message?.content;

if (!raw) {
  return [{
    json: {
      task_id: upstream.task_id,
      agent: "documentation",
      files: [],
      errors: [{ stage: "groq", message: "Réponse Groq vide" }]
    }
  }];
}

let parsed = {};
try {
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch(e) {
  return [{
    json: {
      task_id: upstream.task_id,
      agent: "documentation",
      files: [],
      errors: [{ stage: "parsing", message: e.message }]
    }
  }];
}

const files = Array.isArray(parsed.files)
  ? parsed.files.filter(f => f.path && f.content !== undefined)
  : [];

return [{
  json: {
    task_id: upstream.task_id,
    agent: "documentation",
    files,
    errors: parsed.errors || []
  }
}];

const input = $input.first().json;
return [{
  json: {
    success: false,
    agent: "Agent Documentation",
    task_id: "unknown",
    status: "ERROR",
    error_code: input.error_code,
    error_message: input.error_message,
    approved_for_pipeline: false,
    timestamp: input.timestamp
  }
}];

const input = $input.first().json;

return [{
  json: {
    model: "llama-3.3-70b-versatile",
    messages: [
      { role: "system", content: input.systemPrompt },
      { role: "user", content: input.userPrompt }
    ],
    temperature: 0,
    max_tokens: 8000,
    response_format: { type: "json_object" }
  }
}];

const input = $input.first().json;

const hasFiles = Array.isArray(input.files) && input.files.length > 0;
const hasErrors = Array.isArray(input.errors) && input.errors.length > 0;
const status = hasFiles && !hasErrors ? "PASS" : "FAIL";

return [{
  json: {
    success: status === 'PASS',
    agent: "Agent Documentation",
    task_id: input.task_id,
    status,
    global_score: hasFiles ? 100 : 0,
    approved_for_pipeline: status === 'PASS',
    language: "markdown",
    critical_issues: hasErrors
      ? input.errors.map(e => ({ severity: "high", description: e.message || String(e) }))
      : [],
    warnings: [],
    recommendations: hasFiles
      ? ["Documentation générée avec succès"]
      : ["Régénérer — aucun fichier produit"],
    summary: hasFiles
      ? `${input.files.length} fichier(s) de documentation générés`
      : "Échec de génération documentation",
    dimensions: {
      security: { score: 100 },
      quality: { score: hasFiles ? 100 : 0 }
    },
    timestamp: new Date().toISOString(),
    files: input.files || []
  }
}];

// Fallback déterministe si les deux clés Groq échouent
// Génère un README minimal depuis les données déjà calculées dans Inject Prompt
const upstream = $('Inject Prompt').first().json;
const task_id = upstream.task_id || 'unknown';

// Extraire project_name depuis le systemPrompt
let projectName = 'Application';
const sysPrompt = upstream.systemPrompt || '';
const match = sysPrompt.match(/EXACTEMENT : ([^\n)]+)/);
if (match) projectName = match[1].trim();

const readme = '# ' + projectName + '\n\n' +
  '> *Documentation générée automatiquement par le pipeline SDLC*\n\n' +
  '## Vue d\'ensemble\n\n' +
  'Application générée par le pipeline Forge IA.\n\n' +
  '## Installation\n\n' +
  '```bash\nnpm install\nnpm start\n```\n\n' +
  '## Configuration\n\n' +
  'Créer un fichier `.env` :\n```\nPORT=3000\n```\n\n' +
  '## Note\n\nDocumentation complète non générée (limite quota Groq). ' +
  'Relancer la génération demain pour obtenir le README complet.\n';

return [{
  json: {
    task_id,
    agent: 'documentation',
    files: [{ path: 'README.md', content: readme }],
    errors: [{ stage: 'groq_fallback', message: 'Les deux clés Groq ont atteint leur limite — README minimal généré.' }]
  }
}];
